    """The GoogleMaps endpoints, blocking.

    Reached as :attr:`~tapline.SyncTaplineClient.google_maps`. Anywhere a method takes an
    enum it also takes the enum's raw value.

    Every method raises ``AuthenticationError`` when the API key is rejected,
    ``InsufficientCreditsError`` when the account cannot pay for the call,
    ``RateLimitError`` once automatic retries are exhausted, and
    ``InternalServerError`` when Tapline or the upstream site fails.
    """

    def get_contributor(
        self,
        contributor_id: str,
        *,
        gl: str = "us",
        hl: str = "en",
        limit: int = 10,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GoogleMapsContributor:
        """Get a contributor's profile. Costs 4 credits.

        Args:
            contributor_id: Contributor id, the number in `/maps/contrib/<id>`.
            gl: Two-letter region; sets ranking, currency and units.
            hl: Google language code for the answer's text.
            limit: Latest reviews to include; the profile always lists its 10 latest
                photos.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.google_maps.GoogleMapsContributor`.
        """
        return self._send(
            _get_contributor(contributor_id, gl=gl, hl=hl, limit=limit), timeout=timeout
        )

    def get_directions(
        self,
        *,
        destination: str,
        origin: str,
        gl: str = "us",
        hl: str = "en",
        travel_mode: GoogleMapsTravelModeParam = "best",
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GoogleMapsDirections:
        """Get routes between two places. Costs 2 credits.

        Args:
            destination: A place, an address or `lat,lng`.
            origin: A place, an address or `lat,lng`.
            gl: Two-letter region; sets ranking, currency and units.
            hl: Google language code for the answer's text.
            travel_mode: How to travel.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.google_maps.GoogleMapsDirections`.
        """
        return self._send(
            _get_directions(
                destination=destination, origin=origin, gl=gl, hl=hl, travel_mode=travel_mode
            ),
            timeout=timeout,
        )

    def get_list(
        self,
        list_id: str,
        *,
        gl: str = "us",
        hl: str = "en",
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GoogleMapsList:
        """Get a public shared list and its places. Costs 1 credit.

        Args:
            list_id: The `list_id` of a public list, from a list answer or a share
                link.
            gl: Two-letter region; sets ranking, currency and units.
            hl: Google language code for the answer's text.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.google_maps.GoogleMapsList`.
        """
        return self._send(_get_list(list_id, gl=gl, hl=hl), timeout=timeout)

