    def reverse_geocode(
        self,
        *,
        latitude: float,
        longitude: float,
        gl: str = "us",
        hl: str = "en",
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GoogleMapsReverseGeocode:
        """Find the address and place at a coordinate. Costs 1 credit.

        Args:
            latitude: Latitude, within the ±85.05° the map covers.
            longitude: Longitude.
            gl: Two-letter region; sets ranking, currency and units.
            hl: Google language code for the answer's text.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.google_maps.GoogleMapsReverseGeocode`.
        """
        return self._send(
            _reverse_geocode(latitude=latitude, longitude=longitude, gl=gl, hl=hl), timeout=timeout
        )

    def search(
        self,
        *,
        query: str,
        cursor: str = "",
        gl: str = "us",
        hl: str = "en",
        latitude: float | None = None,
        limit: int = 20,
        longitude: float | None = None,
        min_rating: float | None = None,
        open_now: bool = False,
        zoom: int | None = None,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GoogleMapsSearchPage:
        """Search Google Maps places by text, optionally around a point. Google reranks between calls, so later pages leave out places earlier pages returned and can miss a few that moved. Costs 2 credits.

        Args:
            query: What to search for, as typed in the Maps search box.
            cursor: `pagination.next_cursor` from the previous page; empty for the
                first.
            gl: Two-letter region; sets ranking, currency and units.
            hl: Google language code for the answer's text; hotel check-in and
                check-out times are read only for `en`.
            latitude: Latitude to search around, within the ±85.05° the map covers;
                send with `longitude`.
            limit: Places per page.
            longitude: Longitude to search around; send with `latitude`.
            min_rating: Lowest star rating, 2.0 to 4.5 in steps of 0.5.
            open_now: Only places open at the time of the request.
            zoom: Map zoom around the point, as in `/maps/@lat,lng,14z`; 14 when
                omitted. Needs `latitude` and `longitude`.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.google_maps.GoogleMapsSearchPage`.
        """
        return self._send(
            _search(
                query=query,
                cursor=cursor,
                gl=gl,
                hl=hl,
                latitude=latitude,
                limit=limit,
                longitude=longitude,
                min_rating=min_rating,
                open_now=open_now,
                zoom=zoom,
            ),
            timeout=timeout,
        )

    def get_share_link(
        self,
        code: str,
        *,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GoogleMapsShareLink:
        """Resolve a maps.app.goo.gl share link to the place or list it opens. Costs 1 credit.

        Args:
            code: Code after `maps.app.goo.gl/`.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.google_maps.GoogleMapsShareLink`.
        """
        return self._send(_get_share_link(code), timeout=timeout)

