    def get_traffic(
        self,
        *,
        east: float,
        north: float,
        south: float,
        west: float,
        gl: str = "us",
        hl: str = "en",
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GoogleMapsTraffic:
        """Get the traffic summary for a map area. The box may span at most 1 degree on each side. Costs 1 credit.

        Args:
            east: Eastern longitude of the box.
            north: Northern latitude of the box, within ±85.05°.
            south: Southern latitude of the box, within ±85.05°.
            west: Western longitude of the box; above `east` when the box crosses
                180°.
            gl: Two-letter region Google answers for.
            hl: Google language code for the answer's text.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.google_maps.GoogleMapsTraffic`.
        """
        return self._send(
            _get_traffic(east=east, north=north, south=south, west=west, gl=gl, hl=hl),
            timeout=timeout,
        )

    def get_weather(
        self,
        *,
        latitude: float,
        longitude: float,
        gl: str = "us",
        hl: str = "en",
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> GoogleMapsWeather:
        """Get the current weather at a coordinate. Costs 1 credit.

        Args:
            latitude: Latitude, within the ±85.05° the map covers.
            longitude: Longitude.
            gl: Two-letter region; `us` answers in °F, most regions in °C.
            hl: Google language code for the answer's text.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.google_maps.GoogleMapsWeather`.
        """
        return self._send(
            _get_weather(latitude=latitude, longitude=longitude, gl=gl, hl=hl), timeout=timeout
        )
